CREATE FUNCTION c1_private.nested_floors(flat jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE k text;v jsonb;d text;o text;r jsonb='{}';BEGIN FOR k,v IN SELECT key,value FROM jsonb_each(coalesce(flat,'{}')) LOOP d=split_part(k,':',1);o=CASE WHEN position(':' IN k)>0 THEN substring(k FROM position(':' IN k)+1) ELSE 'global' END;r=jsonb_set(r,ARRAY[d],coalesce(r->d,'{}')||jsonb_build_object(o,v),true);END LOOP;RETURN r;END $$;
CREATE FUNCTION c1_private.merge_floors(a jsonb,b jsonb) RETURNS jsonb LANGUAGE plpgsql IMMUTABLE AS $$ DECLARE d text;k text;v jsonb;ob jsonb;r jsonb=coalesce(a,'{}');BEGIN FOR d,ob IN SELECT key,value FROM jsonb_each(coalesce(b,'{}')) LOOP FOR k,v IN SELECT key,value FROM jsonb_each(ob) LOOP r=jsonb_set(r,ARRAY[d],coalesce(r->d,'{}')||jsonb_build_object(k,greatest(coalesce((r->d->>k)::bigint,0),v::text::bigint)),true);END LOOP;END LOOP;RETURN r;END $$;
CREATE OR REPLACE FUNCTION c1_api.security_startup(n text,q jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=pg_catalog,c1_private,pg_temp AS $$ DECLARE dom text;ob jsonb;k text;v jsonb;actual bigint;d c1_private.deployment;BEGIN d=c1_private.guard(n);IF coalesce((q->>'namespace_probe')::boolean,false) THEN RETURN jsonb_build_object('exists',true,'matched',false);END IF;IF d.source_epoch<>coalesce((q->'epochs'->>'source_epoch')::bigint,d.source_epoch) OR d.credential_epoch<>coalesce((q->'epochs'->>'credential_epoch')::bigint,d.credential_epoch) OR d.restore_generation<>coalesce((q->'epochs'->>'restore_generation')::bigint,d.restore_generation) THEN RETURN jsonb_build_object('matched',false,'reason','EPOCH_MISMATCH');END IF;IF (SELECT security_pending FROM c1_private.transaction_guard WHERE ns=n) IS NOT NULL OR (SELECT execution_pending FROM c1_private.transaction_guard WHERE ns=n) IS NOT NULL THEN RETURN jsonb_build_object('matched',false,'reason','PENDING');END IF;
 FOR dom,ob IN SELECT key,value FROM jsonb_each(coalesce(q->'floors','{}')) LOOP IF dom='execution' THEN CONTINUE;END IF;FOR k,v IN SELECT key,value FROM jsonb_each(ob) LOOP actual=NULL;
 IF dom='credential' THEN actual=d.credential_epoch;ELSIF dom='restore' THEN actual=d.restore_generation;ELSIF dom='identity' THEN SELECT revision INTO actual FROM c1_private.identities WHERE ns=n AND subject=k;ELSIF dom='session' THEN SELECT revision INTO actual FROM c1_private.sessions WHERE ns=n AND hash=decode(k,'hex');ELSIF dom='access' THEN SELECT access_epoch INTO actual FROM c1_private.vouchers WHERE ns=n AND id=k;ELSIF dom='display' THEN SELECT display_epoch INTO actual FROM c1_private.vouchers WHERE ns=n AND id=k;ELSIF dom='grant' THEN SELECT max(revision) INTO actual FROM c1_private.grants WHERE ns=n AND subject=split_part(k,':',1) AND store=split_part(k,':',2);ELSIF dom='payer' THEN SELECT revision INTO actual FROM c1_private.payer_bindings WHERE ns=n AND subject=k;END IF;
 IF actual IS NULL OR actual<v::text::bigint THEN UPDATE c1_private.deployment SET halt=true,reason='JOURNAL_FLOOR' WHERE ns=n;RETURN jsonb_build_object('matched',false,'reason','FLOOR');END IF;END LOOP;END LOOP;RETURN jsonb_build_object('matched',true);END $$;
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA c1_private FROM PUBLIC;
